#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Ticket 14: go live. Creates the dispatch PAT, smoke-tests it on `scan`, has
# scripts/cron_jobs.py create the cron-job.org jobs that run the notifier on its
# schedule, then walks through the login/invite/watch smoke test and tonight's
# first midnight release.
#
# `scripts/go_live.sh rotate` is the PAT-rotation runbook: before the PAT expires
# (GitHub emails a reminder), it makes a new one and swaps it into the jobs.

cd "$(git rev-parse --show-toplevel)"

MODE="${1:-all}"
case "$MODE" in
  all) TOTAL_STAGES=6 ;;
  rotate) TOTAL_STAGES=3 ;;
  *) echo "Usage: scripts/go_live.sh [rotate]" >&2; exit 1 ;;
esac

# The prompts need a keyboard; without one every read comes back empty.
if [[ ! -t 0 ]]; then
  echo "Run this in a terminal window (not through Claude Code's ! prefix): scripts/go_live.sh $*" >&2
  exit 1
fi
REPO=$(gh repo view --json nameWithOwner -q .nameWithOwner 2>/dev/null || true)
SITE="https://${REPO%%/*}.github.io/${REPO#*/}/"
GH_API="https://api.github.com/repos/$REPO"

# dispatch WORKFLOW: POST a workflow_dispatch of main with the PAT, the way
# cron-job.org will. Prints the HTTP status (204 means it worked).
dispatch() {
  curl -s -m 20 -o /dev/null -w '%{http_code}' -X POST "$GH_API/actions/workflows/$1/dispatches" \
    -H "Authorization: Bearer $DISPATCH_PAT" -H 'Accept: application/vnd.github+json' \
    -H 'X-GitHub-Api-Version: 2022-11-28' -d '{"ref":"main"}'
}

# run_since WORKFLOW ISO_TIME: id of the first dispatched run created after ISO_TIME.
run_since() {
  gh run list --workflow "$1" --event workflow_dispatch --limit 5 \
    --json databaseId,createdAt -q "[.[] | select(.createdAt > \"$2\")] | last | .databaseId // empty"
}

if [[ "$MODE" == rotate ]]; then
  banner "Tennis notifier: rotate the dispatch PAT"
else
  banner "Tennis notifier: go live"
fi

# ── Preflight ──────────────────────────────────────────────────────────────
stage "Preflight: GitHub CLI, .env, pushed code and the site"
if [[ -z "$REPO" ]]; then
  warn "gh isn't installed or signed in. Run: gh auth login, then re-run this wizard."; exit 1
fi
note "gh is signed in; working on $REPO."
if git check-ignore -q "$ENV_FILE"; then
  note "$ENV_FILE is git-ignored. Good, the repo is public."
else
  warn "$ENV_FILE isn't git-ignored, and this repo is public. Stopping."; exit 1
fi
if [[ "$MODE" == all ]]; then
  git fetch -q origin main
  if [[ "$(git rev-parse main)" == "$(git rev-parse origin/main)" ]]; then
    note "main is pushed."
  else
    warn "Local main and origin/main differ. Push first (git push), then re-run."; exit 1
  fi
  if gh api "repos/$REPO/contents/.github/workflows/observe.yml" >/dev/null 2>&1; then
    warn "The observe workflow is still on GitHub. Push the commit that removes it."; exit 1
  fi
  note "The old observe logger is gone, so data/ commits have stopped."
  if [[ "$(curl -s -m 20 --retry 3 --retry-all-errors -o /dev/null -w '%{http_code}' "$SITE" || true)" == 200 ]]; then
    note "The site is up at $SITE (BotFather's /setdomain was done in ticket 08)."
  else
    warn "$SITE didn't answer 200. Check the pages workflow, then re-run."; exit 1
  fi
fi
pause

# ── Dispatch PAT ───────────────────────────────────────────────────────────
stage "GitHub: a token cron-job.org can dispatch workflows with"
say "A fine-grained personal access token that can only run this repo's Actions."
[[ "$MODE" == rotate ]] && say "Make a new one; the old one is deleted at the end."
open_url "https://github.com/settings/personal-access-tokens/new"
step "Token name: tennis-notifier dispatch $(date +%y%m%d)"
step "Expiration: Custom, and pick the latest date it allows (a year out)."
step "Repository access: Only select repositories → $REPO"
step "Permissions → Repository permissions → Actions: Read and write"
note "    (Metadata: Read-only is added by itself. Leave everything else off.)"
step "Click 'Generate token' and copy it."
note "The token is kept only in cron-job.org (the API key saved later can read it there)."
while :; do
  DISPATCH_PAT=""
  ask_secret DISPATCH_PAT "Paste the token:"
  status=$(curl -s -m 20 --retry 2 -o /dev/null -w '%{http_code}' "$GH_API/actions/workflows" \
    -H "Authorization: Bearer $DISPATCH_PAT" -H 'Accept: application/vnd.github+json' || true)
  [[ "$status" == 200 ]] && break
  warn "GitHub answered $status for that token. Check its repository and permission, and paste it again."
done
note "The token can see this repo's workflows."
OLD_EXPIRES=$(_existing DISPATCH_PAT_EXPIRES || true)
while :; do
  ask DISPATCH_PAT_EXPIRES "Its expiry date (YYYY-MM-DD, shown on the token page):"
  if [[ ! "$DISPATCH_PAT_EXPIRES" =~ ^20[0-9]{2}-[01][0-9]-[0-3][0-9]$ ]]; then
    warn "That isn't a YYYY-MM-DD date. Try again."
  elif [[ "$MODE" == rotate && "$DISPATCH_PAT_EXPIRES" == "$OLD_EXPIRES" ]]; then
    warn "That's the old token's date. Type the new token's expiry."
  else
    break
  fi
done
write_env DISPATCH_PAT_EXPIRES "$DISPATCH_PAT_EXPIRES"
note "Rotate it before then with: scripts/go_live.sh rotate"
pause

# ── Smoke test: scan ───────────────────────────────────────────────────────
if [[ "$MODE" == all ]]; then
  stage "Smoke test: dispatch scan with the token"
  say "This sends the exact request cron-job.org will send."
  started=$(date -u +%Y-%m-%dT%H:%M:%SZ)
  status=$(dispatch scan.yml || true)
  if [[ "$status" != 204 ]]; then
    warn "GitHub answered $status, not 204. The token needs Actions: Read and write. Re-run this wizard."; exit 1
  fi
  note "Dispatched (204). Waiting for the run to start…"
  run=""
  for _ in $(seq 30); do
    run=$(run_since scan.yml "$started"); [[ -n "$run" ]] && break; sleep 2
  done
  if [[ -z "$run" ]]; then
    warn "No run showed up in a minute. Look at the Actions tab, then re-run."; exit 1
  fi
  gh run watch "$run" --exit-status >/dev/null 2>&1 || warn "The run failed."
  gh run view "$run" --log 2>/dev/null | { grep -E 'court [0-9]|record_scan:|ping' || true; } | sed -E 's/^.*Z //' | while read -r line; do note "$line"; done
  say "Each court should show 6 weeks and some slots, and the last line 'ping: 200'."
  note "Between 23:30 and 00:15 it only logs 'release in progress: scan skipped'; retry after 00:15."
  open_url "https://healthchecks.io/"
  step "The scan check should show as up (green)."
  confirm "Slots stored and the scan check green?" || { warn "Stopping here: look at run $run first."; exit 1; }
fi

# ── cron-job.org ───────────────────────────────────────────────────────────
stage "cron-job.org: create the dispatch jobs"
say "scripts/cron_jobs.py creates (or updates) three jobs, all in Europe/London:"
note "    scan (day):    every 5 min, 07:00–22:55"
note "    scan (night):  every 15 min, 23:00–06:45"
note "    release:       23:45 and 23:50"
open_url "https://console.cron-job.org/settings"
step "Log in (the account used for the observe logger, or a new free one)."
step "Under 'API', create an API key and copy it. Leave the IP list empty."
note "The key goes in .env (git-ignored) so a PAT rotation can reuse it."
ask_secret CRONJOB_API_KEY "Paste the cron-job.org API key:"
write_env CRONJOB_API_KEY "$CRONJOB_API_KEY"
if ! CRONJOB_API_KEY="$CRONJOB_API_KEY" DISPATCH_PAT="$DISPATCH_PAT" python3 scripts/cron_jobs.py \
     | while read -r line; do note "$line"; done; then
  warn "cron-job.org refused. Check the API key, then re-run this wizard."; exit 1
fi
open_url "https://console.cron-job.org/jobs"
step "Three 'tennis-notifier' jobs should be listed and enabled."
if [[ "$MODE" == rotate ]]; then
  open_url "https://github.com/settings/personal-access-tokens"
  step "Wait for the next scan to run (Actions tab), then delete the old token here."
else
  step "Within 5 minutes the 'Last execution' of a scan job shows 'OK' and a new"
  step "scan run appears on GitHub's Actions tab."
  open_url "https://github.com/$REPO/actions/workflows/scan.yml"
fi
pause "Seen it? Press Enter"

# ── Smoke test: members ────────────────────────────────────────────────────
if [[ "$MODE" == all ]]; then
  stage "Smoke test: login, an invite and a new watch"
  open_url "$SITE"
  step "Log in as yourself (the owner)."
  step "Members tab → Create invite link → Copy."
  step "Open the link from a second Telegram account (a friend's phone, or a"
  step "second account) and log in there. It should say who invited it."
  step "On that account, click an hour with a filled \"Free that week\" dot and Save."
  step "That account should get a Telegram DM about the free slot within seconds."
  step "Afterwards you can remove it from the Members tab."
  confirm "Did the new-watch DM arrive?" || warn "No DM: check the api function's logs in Supabase."

  # ── First midnight release ────────────────────────────────────────────
  stage "Tonight: watch the first midnight release"
  say "From 23:45 London time:"
  step "The 23:45 release run logs 'claimed by run …' and waits. The 23:50 one queues"
  step "behind it, then logs 'not claimed … exiting' once the first has finished."
  step "Scans dispatched while the claim is held log 'release in progress: scan skipped'."
  step "Just after midnight the log shows 'probe: … open' (or 'still not seen open …"
  step "recording the release anyway'), 'record_release: N messages' and, after 00:00:01,"
  step "'ping: 200'. 'ping: withheld' means the bot token got a 401. Anyone watching an"
  step "hour on the new day gets a '🎾 Just released' DM."
  step "Healthchecks: the release check turns green. If it hasn't by 00:20, it alarms."
  note "The release page: https://github.com/$REPO/actions/workflows/release.yml"
  pause "Got it? Press Enter (this ends the wizard)"
fi

finish
